import type { Metadata } from "next";

import { siteDescription, siteName } from "@/lib/content/site";

/**
 * Public origin for canonical URLs, sitemaps, and social cards.
 * Set NEXT_PUBLIC_SITE_URL in each environment; the fallback keeps local
 * builds and preview deployments valid.
 */
export const siteUrl = (
  process.env.NEXT_PUBLIC_SITE_URL || "https://sdc-iiserb.vercel.app"
).replace(/\/$/, "");

/** Short brand suffix used in document titles: "About | SDC IISER Bhopal". */
export const titleSuffix = "SDC IISER Bhopal";

/** Default 1200×630 social card, generated by `scripts/generate-og-image.mjs`. */
export const socialImage = {
  url: `${siteUrl}/og.png`,
  width: 1200,
  height: 630,
  alt: `${siteName}, IISER Bhopal`,
};

/** Absolute URL for a site path ("/" or "/events"). */
export function absoluteUrl(path = "/") {
  return path === "/" ? siteUrl : `${siteUrl}${path}`;
}

type PageMetadataOptions = {
  title: string;
  description: string;
  /** Route path, e.g. "/events". Used for the canonical URL. */
  path: string;
  /** Keep utility pages (login, forms) out of search results. */
  noIndex?: boolean;
  /** Extra Open Graph fields for article-like pages. */
  openGraph?: Metadata["openGraph"];
};

/**
 * Consistent page metadata: unique title/description, canonical URL, and a
 * social card. Next.js replaces (rather than merges) nested metadata, so every
 * page must set its own Open Graph block or it inherits the home page's.
 */
export function pageMetadata({
  title,
  description,
  path,
  noIndex = false,
  openGraph,
}: PageMetadataOptions): Metadata {
  const url = absoluteUrl(path);
  const socialTitle = path === "/" ? title : `${title} | ${titleSuffix}`;

  return {
    title,
    description,
    alternates: { canonical: url },
    ...(noIndex ? { robots: { index: false, follow: true } } : {}),
    openGraph: {
      type: "website",
      siteName,
      locale: "en_IN",
      title: socialTitle,
      description,
      url,
      images: [socialImage],
      ...openGraph,
    },
    twitter: {
      card: "summary_large_image",
      title: socialTitle,
      description,
      images: [socialImage.url],
    },
  };
}

/** Home page metadata, also used as the site-wide default. */
export function homeMetadata(): Metadata {
  return pageMetadata({
    title: "Student Development Council (SDC), IISER Bhopal",
    description: siteDescription,
    path: "/",
  });
}
